task sum_digits(n: int) returns (r: int)
  requires n >= 0
  ensures r == sum_of_digits(n)
{
  r := 0;
  var i: int := n;
  while i > 0
    invariant r == sum_of_digits(i)
    invariant i >= 0
    decreases i
  {
    var digit: int := i % 10;
    r := r + digit;
    i := i / 10;
  }
}
